  const lettersPage = (el, p, app) => NS.crud(el, app, { col: 'letters', title: 'Evrak Kayıtları', sub: 'Gelen ve giden evrak, tarih ve sıra numarasıyla', single: 'Evrak', addLabel: 'Evrak ekle', emptyIcon: 'file', fields: [{ name: 'dir', label: 'Yön', type: 'select', options: [{ value: 'gelen', label: 'Gelen' }, { value: 'giden', label: 'Giden' }] }, { name: 'date', label: 'Tarih', type: 'date', required: true }, { name: 'party', label: 'Kurum / kişi', required: true }, { name: 'subject', label: 'Konu', required: true, full: true }], defaults: () => ({ dir: 'gelen', date: today() }), beforeSave: (v, rec) => { if (!rec) v.no = db.all('letters').reduce((x, y) => Math.max(x, y.no || 0), 0) + 1; }, canDelete: () => 'Evrak kaydı silinmez, sıra numarası boş kalmamalı. Yanlış kaydı düzeltin.', sort: (a, b) => (b.no || 0) - (a.no || 0), searchFields: (x) => [x.party, x.subject, x.no], filters: [{ value: 'all', label: 'Tümü' }, { value: 'g', label: 'Gelen', test: (x) => x.dir === 'gelen' }, { value: 'c', label: 'Giden', test: (x) => x.dir === 'giden' }], columns: [{ key: 'no', label: 'Sıra', render: (x) => `<b>${x.no}</b>` }, { key: 'date', label: 'Tarih', render: (x) => NS.date(x.date) }, { key: 'dir', label: 'Yön', render: (x) => (x.dir === 'gelen' ? badge('Gelen', 'info') : badge('Giden', 'acc')) }, { key: 'party', label: 'Kurum / kişi' }, { key: 'subject', label: 'Konu' }] });
  const postsPage = (el, p, app) => NS.crud(el, app, { col: 'posts', title: 'Duyurular', sub: hasDues() ? 'Üye portalında görünür; isterseniz SMS ile gönderin' : 'Duyuruları SMS ile gönderin', single: 'Duyuru', addLabel: 'Duyuru yaz', emptyIcon: 'bell', fields: [{ name: 'title', label: 'Başlık', required: true, full: true }, { name: 'body', label: 'Metin', type: 'textarea', required: true, full: true }, { name: 'date', label: 'Tarih', type: 'date' }], defaults: () => ({ date: today() }), sort: (a, b) => String(b.date).localeCompare(String(a.date)), columns: [{ key: 'date', label: 'Tarih', render: (x) => NS.date(x.date) }, { key: 'title', label: 'Başlık', render: (x) => `<b>${esc(x.title)}</b><div class="small faint">${esc(String(x.body || '').slice(0, 90))}</div>` }, { label: 'SMS', render: (x) => (x.smsOk ? badge(`${x.smsOk} kişi`, 'ok') : '-') }], extraActions: [{ icon: 'send', act: 'sms', title: 'SMS gönder' }], onAction: async (a, x, draw) => { const L = db.all('members', (m) => m.status === 'aktif' && m.phone); if (!L.length) return toast('Telefonu kayıtlı kişi yok', 'err'); if (!(await confirm(`${L.length} kişiye SMS gönderilsin mi?`, { ok: 'Gönder', danger: false }))) return; const n = await NS.smsBatch(db, L.map((m) => ({ to: m.phone, name: m.name, text: `${S().bizName}: ${x.title}. ${x.body}`.slice(0, 300) })), 'duyuru'); if (n.ok) { x.smsOk = (x.smsOk || 0) + n.ok; db.save(); } draw(); } });

